"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["48351"],{51629(e,a,t){t.r(a),t.d(a,{metadata:()=>n,default:()=>d,frontMatter:()=>s,contentTitle:()=>r,toc:()=>h,assets:()=>l});var n=JSON.parse('{"id":"tianya/linbiaononame","title":"","description":"This lady rarely watches TV. Today I accidentally caught CCTV\'s The Eighth Route Army. What this lady was most concerned about was how Marshal Lin Biao was treated. I never imagined that China\'s most brilliant military marshal of the last century would be treated as if he\'d lost his name.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/linbiaononame.md","sourceDirName":"tianya","slug":"/tianya/linbiaononame","permalink":"/en/tianya/linbiaononame","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"linbiaononame","title":"","hide_table_of_contents":true,"sidebar_label":"CCTV, has the name of China\'s most capable marshal of the last century been erased?"},"sidebar":"tianyaSidebar","previous":{"title":"\\"Military strength is the necessary and sufficient condition for a strong nation\\" is a product of typical male lower-body thinking","permalink":"/en/tianya/bottombodythinking"},"next":{"title":"Based on female capability, a woman should consume 100,000 male ape-men in a lifetime!","permalink":"/en/tianya/onefemale100000apes"}}'),i=t(74848),o=t(28453);let s={id:"linbiaononame",title:"",hide_table_of_contents:!0,sidebar_label:"CCTV, has the name of China's most capable marshal of the last century been erased?"},r="CCTV -- Has China's Most Brilliant Military Marshal of the Last Century Lost His Name?",l={},h=[];function c(e){let a={em:"em",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"cctv----has-chinas-most-brilliant-military-marshal-of-the-last-century-lost-his-name",children:"CCTV -- Has China's Most Brilliant Military Marshal of the Last Century Lost His Name?"})}),"\n",(0,i.jsxs)(a.p,{children:["This lady rarely watches TV. Today I accidentally caught CCTV's ",(0,i.jsx)(a.em,{children:"The Eighth Route Army"}),". What this lady was most concerned about was how Marshal Lin Biao was treated. I never imagined that China's most brilliant military marshal of the last century would be treated as if he'd lost his name."]}),"\n",(0,i.jsx)(a.p,{children:"In the TV drama, everyone else is addressed by surname plus title or called by name directly. Only Lin Biao is called \"Division Commander.\" For the new generation that has little exposure to history, they probably don't even know who this \"Division Commander\" is. The most laughable thing is that the actor selected looks nothing like Marshal Lin Biao. You should know that at the time Lin Biao's health was already not very good -- just because his name is Lin Biao, does that mean you can select a hulking brute without caring whether the resemblance is there? Why must everyone else's accent match, while Lin Biao can lose even his appearance and name? CCTV -- has China's most brilliant military marshal of the last century lost his name?"}),"\n",(0,i.jsx)(a.p,{children:'It can be said this way: regardless of what happened to Lin Biao afterward, his military talent and military achievements can never be forgotten. Who created the miracle of a single company defeating an entire division? Who led troops in the First Anti-Encirclement Campaign and captured Nationalist 18th Division Commander Zhang Huizan alive? Who in his first command of large-scale army operations annihilated the Nationalist 52nd Division in the Battle of Huangpo? Who commanded the 115th Division at Pingxingguan to wipe out over 1,000 men of the Japanese Sakagaki Division\'s 21st Brigade -- known as the "Flower of the Army" -- shattering the myth of Japanese invincibility? Who was called a genius military commander by Stalin and invited to join the Soviet General Staff\'s work? Who in 3 years successively annihilated 1.08 million troops under the commands of three famous generals -- Du Yuming, Chen Cheng, and Wei Lihuang -- liberating the entire Northeast as a resource-rich strategic zone and cultivating a powerful strategic reserve? Who took only 29 hours to capture Tianjin\'s city defenses, which Fu Zuoyi claimed could hold for half a year as "impregnable"? Who fought from the white mountains and black waters to the farthest corners of the land, sweeping through thousands of troops like rolling up a mat? These questions all have one common answer: Lin Biao.'}),"\n",(0,i.jsx)(a.p,{children:"In the 21st century, we cannot avoid the necessity and obligation of studying the Lin Biao question!"})]})}function d(e={}){let{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,a,t){t.d(a,{R:()=>s,x:()=>r});var n=t(96540);let i={},o=n.createContext(i);function s(e){let a=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function r(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),n.createElement(o.Provider,{value:a},e.children)}}}]);